p"><label class="form-label">Correo</label><input required type="email" name="correo" value="<?=e($registro['correo']??'')?>"></div><div class="form-group"><label class="form-label">Usuario</label><input required name="usuario" value="<?=e($registro['usuario']??'')?>"></div><div class="form-group"><label class="form-label">Rol</label><select required name="id_rol"><?php foreach($roles as $r):?><option value="<?=$r['id_rol']?>" <?=($registro['id_rol']??'')==$r['id_rol']?'selected':''?>><?=e($r['nombre_rol'])?></option><?php endforeach;?></select></div><div class="form-group"><label class="form-label">Estado</label><select name="estado"><option value="activo" <?=($registro['estado']??'activo')==='activo'?'selected':''?>>Activo</option><option value="inactivo" <?=($registro['estado']??'')==='inactivo'?'selected':''?>>Inactivo</option></select></div><div class="form-group"><label class="form-label">Teléfono</label><input name="telefono" value="<?=e($registro['telefono']??'')?>"></div><div class="form-group"><label class="form-label">Contraseña <?= $registro?'(opcional)':''?></label><input type="password" name="clave" <?= $registro?'':'required'?>></div></div><div class="actions"><button class="btn btn-primary">Guardar</button><a class="btn btn-light" href="/controllers/usuarios.php">Cancelar</a></div></form></div></div><?php endif;?><?php include __DIR__.'/../layouts/footer.php';?>
